using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;
namespace ServiceTool{internal static class FooterPaddingTests{
static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var n in Walk(c))yield return n;}}
[STAThread]static int Main(){int checks=0;try{foreach(bool dark in new[]{false,true})foreach(float scale in new[]{1F,1.25F,1.5F,2F})foreach(Form f in new Form[]{new ManagerHub(),new InitialSystemSettingsForm(true)})using(f){((ManagerModuleForm)f).SetTheme(dark,false);f.Show();Application.DoEvents();if(scale!=1)f.Scale(new SizeF(scale,scale));for(int i=0;i<20;i++)Application.DoEvents();var buttons=Walk(f).OfType<BrandButton>().Where(b=>b.Text=="В меню"||b.Text=="Скачать комплект"||b.Text=="Инструкция"||b.Text=="О программе").ToArray();foreach(var b in buttons){int top=b.Top,bottom=b.Parent.ClientSize.Height-b.Bottom;if(top<8*scale||bottom<8*scale)throw new Exception("Tight footer "+f.GetType().Name+" "+b.Text+" top="+top+" bottom="+bottom);checks++;}using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"footer-"+f.GetType().Name+"-"+dark+"-"+scale.ToString(System.Globalization.CultureInfo.InvariantCulture)+".png"));}f.Close();}Console.WriteLine("PASS: "+checks+" footer top/bottom padding assertions; both themes, 100–200%. No system changes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}
